<script setup lang="ts">
const props=withDefaults(defineProps<{locale?:'nl'|'en'}>(),{locale:'nl'})
const nl=computed(()=>props.locale==='nl')
type Scenario='direct'|'research'
type Step={id:string;titleNl:string;titleEn:string;detailNl:string;detailEn:string;actor:'person'|'orchestrator'|'model'|'tool'|'answer'}
const scenario=ref<Scenario>('research')
const current=ref(0)
const playing=ref(false)
let timer:ReturnType<typeof setInterval>|undefined
const steps=computed<Step[]>(()=>scenario.value==='direct'?[
 {id:'question',titleNl:'1. Vraag',titleEn:'1. Question',detailNl:'“Leg kort uit waarom de lucht blauw is.”',detailEn:'“Briefly explain why the sky is blue.”',actor:'person'},
 {id:'context',titleNl:'2. Invoer samenstellen',titleEn:'2. Assemble input',detailNl:'De actuele vraag wordt gecombineerd met relevante gesprekscontext, instructies en een beschrijving van beschikbare hulpmiddelen.',detailEn:'The current question is combined with relevant conversation context, instructions and a description of available tools.',actor:'orchestrator'},
 {id:'interpret',titleNl:'3. Modelpassage',titleEn:'3. Model pass',detailNl:'Het taalmodel verwerkt de volledige invoer en bepaalt dat het met algemene, aangeleerde kennis direct kan antwoorden.',detailEn:'The language model processes the full input and determines that it can answer directly from general learned knowledge.',actor:'model'},
 {id:'answer',titleNl:'4. Antwoord',titleEn:'4. Answer',detailNl:'Het model genereert het antwoord token voor token. Er is geen externe zoekactie uitgevoerd.',detailEn:'The model generates its answer token by token. No external search was performed.',actor:'answer'}
]:[
 {id:'question',titleNl:'1. Vraag',titleEn:'1. Question',detailNl:'“Wat veranderde dit jaar in het Nederlandse AI-beleid, en wat betekent dat?”',detailEn:'“What changed in Dutch AI policy this year, and what does it mean?”',actor:'person'},
 {id:'context',titleNl:'2. Invoer samenstellen',titleEn:'2. Assemble input',detailNl:'De applicatie voegt de actuele vraag samen met instructies, relevante gesprekscontext en informatie over beschikbare zoek- en leestools.',detailEn:'The application combines the current question with instructions, relevant conversation context and information about available search and reading tools.',actor:'orchestrator'},
 {id:'interpret',titleNl:'3. Eerste modelpassage',titleEn:'3. First model pass',detailNl:'Het model interpreteert doel, begrippen en tijdsgevoeligheid. Het kiest als volgende actie actuele bronnen zoeken. Een volledig uitgeschreven intern redeneerplan is daarvoor niet noodzakelijk.',detailEn:'The model interprets the goal, concepts and time sensitivity. It chooses current-source search as its next action. This does not require a fully written-out internal reasoning plan.',actor:'model'},
 {id:'search',titleNl:'4. Zoekopdracht',titleEn:'4. Search request',detailNl:'Het model produceert een gestructureerde toolaanroep. De applicatie voert die buiten het taalmodel uit.',detailEn:'The model emits a structured tool call. The application executes it outside the language model.',actor:'tool'},
 {id:'results',titleNl:'5. Bronnen terug',titleEn:'5. Sources returned',detailNl:'Zoekresultaten of gelezen pagina’s worden als nieuwe context aan het gesprek toegevoegd, met broninformatie waar beschikbaar.',detailEn:'Search results or retrieved pages are added to the conversation as new context, including source information where available.',actor:'orchestrator'},
 {id:'evaluate',titleNl:'6. Nieuwe modelpassage',titleEn:'6. New model pass',detailNl:'Het model beoordeelt bruikbaarheid, vergelijkt bronnen en kan nog een zoek- of leesactie aanvragen. Deze lus kan zich herhalen.',detailEn:'The model assesses usefulness, compares sources and may request another search or reading action. This loop can repeat.',actor:'model'},
 {id:'answer',titleNl:'7. Antwoord met bronnen',titleEn:'7. Sourced answer',detailNl:'Wanneer voldoende informatie beschikbaar is, formuleert het model een antwoord uit vraag, instructies, context en opgehaalde bronnen.',detailEn:'Once enough information is available, the model composes an answer from the question, instructions, context and retrieved sources.',actor:'answer'}
])
const actorLabel=(actor:Step['actor'])=>({person:nl.value?'Mens':'Person',orchestrator:nl.value?'Applicatie':'Application',model:nl.value?'Taalmodel':'Language model',tool:nl.value?'Extern hulpmiddel':'External tool',answer:nl.value?'Uitvoer':'Output'}[actor])
function stop(){playing.value=false;if(timer){clearInterval(timer);timer=undefined}}
function reset(){stop();current.value=0}
function setScenario(value:Scenario){scenario.value=value;reset()}
function next(){if(current.value<steps.value.length-1)current.value++;else stop()}
function play(){if(playing.value){stop();return}if(current.value===steps.value.length-1)current.value=0;playing.value=true;timer=setInterval(next,1050)}
onUnmounted(stop)
</script>

<template>
 <section class="flow-explorer">
  <header><div><p>{{nl?'Interactieve procesweergave':'Interactive process view'}}</p><h3>{{nl?'Hoe wordt een vraag een antwoord?':'How does a question become an answer?'}}</h3></div><button type="button" @click="reset">{{nl?'Opnieuw':'Reset'}}</button></header>
  <div class="scenario-switch" role="group" :aria-label="nl?'Type vraag':'Question type'">
   <button type="button" :class="{active:scenario==='direct'}" @click="setScenario('direct')">{{nl?'Algemene vraag':'General question'}}</button>
   <button type="button" :class="{active:scenario==='research'}" @click="setScenario('research')">{{nl?'Actuele onderzoeksvraag':'Current research question'}}</button>
  </div>
  <div class="route" :style="{'--count':steps.length}">
   <template v-for="(step,index) in steps" :key="step.id">
    <button type="button" :class="['stage',step.actor,{active:index===current,passed:index<current}]" @click="current=index;stop()"><small>{{actorLabel(step.actor)}}</small><b>{{nl?step.titleNl:step.titleEn}}</b></button>
    <span v-if="index<steps.length-1" :class="['arrow',{passed:index<current}]" aria-hidden="true">→</span>
   </template>
  </div>
  <div class="stage-detail"><span>{{actorLabel(steps[current].actor)}}</span><h4>{{nl?steps[current].titleNl:steps[current].titleEn}}</h4><p>{{nl?steps[current].detailNl:steps[current].detailEn}}</p></div>
  <div class="controls"><button type="button" @click="play">{{playing?(nl?'Pauze':'Pause'):(nl?'Speel proces af':'Play process')}}</button><button type="button" :disabled="current===steps.length-1" @click="next">{{nl?'Volgende stap':'Next step'}}</button><span>{{current+1}} / {{steps.length}}</span></div>
  <div class="legend"><span class="person">{{nl?'Vraag':'Question'}}</span><span class="orchestrator">{{nl?'Context en regie':'Context and orchestration'}}</span><span class="model">{{nl?'Modelpassage':'Model pass'}}</span><span class="tool">{{nl?'Externe actie':'External action'}}</span><span class="answer">{{nl?'Antwoord':'Answer'}}</span></div>
  <details><summary>{{nl?'Wat deze weergave vereenvoudigt':'What this view simplifies'}}</summary><p>{{nl?'Dit is een functioneel schema, geen weergave van verborgen interne redeneerstappen. Producten verschillen in routering, geheugen, zoektechniek, veiligheidscontroles en het aantal modelpassages. Een model kan een volgende actie kiezen zonder eerst een volledig, leesbaar handelplan uit te schrijven.':'This is a functional diagram, not a view into hidden internal reasoning. Products differ in routing, memory, retrieval, safety checks and number of model passes. A model can select a next action without first writing a complete human-readable plan.'}}</p></details>
 </section>
</template>

<style scoped>
.flow-explorer{--ink:#17352f;--muted:#65736e;--line:#cbd6d1;margin:1rem 0;padding:1rem;border:1px solid var(--line);border-radius:15px;background:#f7f8f5;color:var(--ink);font:400 .76rem/1.45 system-ui,sans-serif}.flow-explorer *{box-sizing:border-box}.flow-explorer header{display:flex;justify-content:space-between;gap:1rem;align-items:start}.flow-explorer header p{margin:0;color:#55746c;font-size:.6rem;font-weight:750;letter-spacing:.1em;text-transform:uppercase}.flow-explorer h3{margin:.12rem 0;font:750 clamp(1.05rem,2.4vw,1.45rem)/1.15 system-ui}.flow-explorer button{border:1px solid #b9c7c1;border-radius:999px;background:#fff;padding:.45rem .7rem;color:var(--ink);font:650 .64rem system-ui;cursor:pointer}.flow-explorer button:disabled{opacity:.4;cursor:default}.scenario-switch{display:flex;gap:.4rem;margin:1rem 0}.scenario-switch button.active,.controls button:first-child{background:#2f6f65;color:#fff;border-color:#2f6f65}.route{display:flex;align-items:stretch;width:100%;max-width:100%;overflow-x:auto;overscroll-behavior-inline:contain;padding:.35rem .2rem .85rem;scrollbar-gutter:stable}.stage{display:grid;align-content:start;flex:0 0 132px!important;width:132px!important;min-width:132px!important;max-width:132px!important;min-height:74px;margin:0!important;border-radius:9px!important;text-align:left;white-space:normal;overflow-wrap:anywhere}.stage small{display:block;margin-bottom:.16rem;color:var(--muted);font-size:.52rem;text-transform:uppercase;letter-spacing:.05em}.stage b{display:block;font-size:.66rem;line-height:1.25}.stage.person{border-top:3px solid #9b744a}.stage.orchestrator{border-top:3px solid #587997}.stage.model{border-top:3px solid #6b668f}.stage.tool{border-top:3px solid #aa654d}.stage.answer{border-top:3px solid #39766c}.stage.active{outline:2px solid #183c36;outline-offset:2px}.stage.passed{background:#e9f0ed}.arrow{display:grid;place-items:center;flex:0 0 24px;width:24px;min-width:24px;align-self:center;color:#a5afab;font-size:.85rem;line-height:1}.arrow.passed{color:#2f6f65;font-weight:800}.stage-detail{min-height:130px;padding:.85rem;border-radius:10px;background:#183c36;color:#fff}.stage-detail span{font-size:.55rem;opacity:.68;text-transform:uppercase;letter-spacing:.07em}.stage-detail h4{margin:.15rem 0 .35rem;font:750 .9rem system-ui}.stage-detail p{margin:0;max-width:75ch;opacity:.9}.controls{display:flex;align-items:center;gap:.45rem;margin-top:.7rem}.controls span{margin-left:auto;color:var(--muted)}.legend{display:flex;flex-wrap:wrap;gap:.35rem .7rem;margin-top:.8rem;color:var(--muted);font-size:.58rem}.legend span:before{content:'';display:inline-block;width:.55rem;height:.55rem;margin-right:.28rem;border-radius:50%;background:#999}.legend .person:before{background:#9b744a}.legend .orchestrator:before{background:#587997}.legend .model:before{background:#6b668f}.legend .tool:before{background:#aa654d}.legend .answer:before{background:#39766c}.flow-explorer details{margin-top:.75rem;padding:.6rem .7rem;border:1px solid var(--line);border-radius:8px;background:#fff}.flow-explorer summary{cursor:pointer;font-weight:700}.flow-explorer details p{margin:.4rem 0 0;color:var(--muted);font-size:.66rem}@media(max-width:620px){.flow-explorer header{display:grid}.scenario-switch{display:grid;grid-template-columns:1fr 1fr}.scenario-switch button{border-radius:8px}.route{display:grid;grid-template-columns:minmax(0,1fr);justify-items:stretch;overflow:visible;padding:.25rem 0 .75rem}.stage{width:100%!important;min-width:0!important;max-width:none!important;min-height:0}.arrow{width:100%;min-width:0;height:22px;transform:rotate(90deg)}.stage-detail{min-height:160px}}
</style>
